    ["Round 5"] = "Раунд 5",
    ["You have caught a glimpse of the true face of the pathway, where the costs of power and reason coexist, and you have become an entity that influences the situation."] = "Впервые вы видите истинное лицо пути, цену силы и здравомыслия, сосуществующих, и это стало сущностью, влияющей на ситуацию.",
    ["David "] = "Дэвид",
